// Agency API — lets the agency (BDT) monitor and control this website with an API key.
//
//   Base URL:  https://<site>/api/agency/v1
//   Auth:      Authorization: Bearer jjj_live_…    (or header X-Api-Key)
//
// Keys are generated by the owner in the dashboard's hidden Connections window.
// Only a SHA-256 hash of each key is stored; the key itself is shown once.
// Every call is written to an audit log. Keys can be read-only or full control,
// and can be revoked at any time. Optional signed webhooks push alerts to the agency.
import crypto from 'node:crypto';

const PREFIX = 'jjj_live_';
const sha = (s) => crypto.createHash('sha256').update(s).digest('hex');
const nowISO = () => new Date().toISOString();

export function mountAgency(app, ctx) {
  const { store, monitor, toAdmins, adminView, config, itemsById, changeStatus, STATUSES, live, TAX_RATE, business, pickupWindow, staffOnly } = ctx;

  const keys = () => store.kv('agency:keys', []);
  const audit = () => store.kv('agency:audit', []);
  let auditT = 0, auditBuf = null;
  function log(entry) {
    auditBuf ??= [...audit()];
    auditBuf.unshift({ at: nowISO(), ...entry });
    if (auditBuf.length > 600) auditBuf.length = 600;
    clearTimeout(auditT);
    auditT = setTimeout(() => { store.setKV('agency:audit', auditBuf).catch(() => {}); auditBuf = null; }, 1200);
  }
  const auditNow = () => auditBuf ?? audit();

  /* ── site status / gate ─────────────────────────────────────────────── */
  const site = () => {
    const s = store.settings();
    return { online: s.siteOnline !== false, offlineMessage: s.offlineMessage || '', announcement: s.announcement || { text: '', active: false } };
  };
  const OPEN_PATHS = [/^\/admin/, /^\/api\/admin/, /^\/api\/staff/, /^\/api\/agency/, /^\/healthz/, /^\/assets\//, /^\/photos\//, /^\/favicon/, /^\/apple-touch-icon/, /^\/api\/telemetry/];
  function siteGate(req, res, next) {
    const st = site();
    if (st.online || OPEN_PATHS.some((r) => r.test(req.path))) return next();
    res.locals.errorRecorded = true; // switched off on purpose — not an error
    if (req.path.startsWith('/api/')) return res.status(503).json({ error: st.offlineMessage || 'The website is temporarily offline.', offline: true });
    res.status(503).setHeader('Retry-After', '600');
    res.setHeader('Cache-Control', 'no-store');
    res.type('html').send(offlinePage(st.offlineMessage, business));
  }

  async function setSite(patch, by) {
    const prev = site();
    const s = await store.setSettings(patch);
    toAdmins('settings', { ...s, taxRate: TAX_RATE });
    const now = site();
    if (prev.online !== now.online) { emit(now.online ? 'site.online' : 'site.offline', { by, message: now.offlineMessage }); monitor.record({ source: 'control', level: 'info', message: `Website switched ${now.online ? 'ON' : 'OFF'} by ${by}` }); }
    return now;
  }

  /* ── webhook push to the agency ──────────────────────────────────────── */
  const hook = () => store.kv('agency:webhook', { url: '', secret: '', events: ['error', 'site', 'db', 'order.new'], active: false, lastStatus: null });
  const throttle = new Map();
  function emit(event, data) {
    for (const r of live.agencyClients) r.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
    const h = hook();
    if (!h.active || !h.url) return;
    const family = event.split('.')[0];
    if (!h.events.includes(event) && !h.events.includes(family)) return;
    const tkey = event + (data?.message || '');
    if (event === 'error' && Date.now() - (throttle.get(tkey) || 0) < 60000) return;
    throttle.set(tkey, Date.now());
    send(h, event, data).catch(() => {});
  }
  async function send(h, event, data) {
    const body = JSON.stringify({ event, site: business.name, url: process.env.RENDER_EXTERNAL_URL || null, at: nowISO(), data });
    const sig = crypto.createHmac('sha256', h.secret).update(body).digest('hex');
    try {
      const r = await fetch(h.url, { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-Joyfull-Event': event, 'X-Joyfull-Signature': `sha256=${sig}` }, body, signal: AbortSignal.timeout(8000) });
      await store.setKV('agency:webhook', { ...hook(), lastStatus: { at: nowISO(), ok: r.ok, code: r.status } });
      return r.status;
    } catch (e) {
      await store.setKV('agency:webhook', { ...hook(), lastStatus: { at: nowISO(), ok: false, error: e.message } });
      throw e;
    }
  }

  /* ── what the agency sees ─────────────────────────────────────────────── */
  function ordersSummary() {
    const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Chicago' }).format(new Date());
    const day = (d) => new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Chicago' }).format(new Date(d));
    const all = store.orders(), t = all.filter((o) => day(o.createdAt) === today);
    const valid = t.filter((o) => o.status !== 'cancelled');
    const prepTimes = valid.map((o) => { const a = o.history.find((h) => h.status === 'received'), b = o.history.find((h) => h.status === 'ready'); return a && b ? (new Date(b.at) - new Date(a.at)) / 60000 : null; }).filter((x) => x != null);
    return {
      today: { orders: t.length, cancelled: t.length - valid.length, ordered: +valid.reduce((s, o) => s + o.total, 0).toFixed(2),
        newWaiting: t.filter((o) => o.status === 'received').length, preparing: t.filter((o) => o.status === 'preparing').length,
        readyForPickup: t.filter((o) => o.status === 'ready').length, pickedUp: t.filter((o) => o.status === 'completed').length,
        avgPrepMinutes: prepTimes.length ? +(prepTimes.reduce((a, b) => a + b, 0) / prepTimes.length).toFixed(1) : null },
      late: all.filter((o) => ['received', 'preparing'].includes(o.status) && new Date(o.estReadyAt) < Date.now()).map((o) => ({ number: o.number, minutesLate: Math.round((Date.now() - new Date(o.estReadyAt)) / 60000) })),
      lastOrderAt: all[0]?.createdAt ?? null, totalOrdersStored: all.length,
    };
  }
  function alerts() {
    const out = [], s = store.settings(), st = site(), h = monitor.health(), tr = monitor.traffic(), ec = monitor.errorCounts(), os = ordersSummary(), cfg = config();
    if (!st.online) out.push({ level: 'critical', code: 'site_offline', message: 'The website is switched OFF.' });
    if (!h.database.ok) out.push({ level: 'critical', code: 'db_down', message: `Database unreachable since ${h.database.downSince}: ${h.database.error}` });
    if (store.kind !== 'postgres' && process.env.NODE_ENV === 'production') out.push({ level: 'critical', code: 'no_database', message: 'Orders are not being saved to Supabase (DATABASE_URL not set).' });
    if (!process.env.OWNER_PASSWORD && process.env.NODE_ENV === 'production') out.push({ level: 'critical', code: 'no_owner_password', message: 'OWNER_PASSWORD is not set — nobody can sign in to the dashboard.' });
    if (tr.last1h.requests > 20 && tr.last1h.errorRate > 5) out.push({ level: 'critical', code: 'error_rate', message: `${tr.last1h.errorRate}% of requests failed in the last hour.` });
    if (ec.serverLastHour > 0) out.push({ level: 'warning', code: 'server_errors', message: `${ec.serverLastHour} server error(s) in the last hour.` });
    if (ec.browserLastHour > 0) out.push({ level: 'warning', code: 'browser_errors', message: `${ec.browserLastHour} browser error(s) reported by visitors in the last hour.` });
    if (tr.last1h.p95ms > 2000) out.push({ level: 'warning', code: 'slow', message: `Slow responses: 95% of requests took up to ${tr.last1h.p95ms} ms.` });
    if (s.ordersPaused) out.push({ level: 'warning', code: 'ordering_paused', message: `Online ordering is paused${s.pauseMessage ? `: “${s.pauseMessage}”` : ''}.` });
    if (os.late.length) out.push({ level: 'warning', code: 'late_orders', message: `${os.late.length} order(s) past their ready time.` });
    if ((s.soldOut || []).length) out.push({ level: 'info', code: 'sold_out', message: `${s.soldOut.length} menu item(s) marked sold out.` });
    if (cfg.pickup.asap && os.today.newWaiting > 0 && live.adminClients.size === 0) out.push({ level: 'warning', code: 'nobody_watching', message: 'New orders are waiting and no staff dashboard is open.' });
    return out;
  }
  function status() {
    const cfg = config(), st = site(), s = store.settings();
    return {
      site: { name: business.name, url: process.env.RENDER_EXTERNAL_URL || null, online: st.online, offlineMessage: st.offlineMessage, announcement: st.announcement,
        ordering: { paused: !!s.ordersPaused, message: s.pauseMessage || '', openNow: cfg.pickup.asap, lastOrderAt: cfg.pickup.lastOrderAt || null, nextOpening: cfg.pickup.next || null, prepMinutes: cfg.prepMinutes, taxRate: TAX_RATE },
        soldOut: (s.soldOut || []).map((id) => ({ id, name: itemsById[id]?.name ?? id })) },
      health: monitor.health(), traffic: monitor.traffic(), errors: { ...monitor.errorCounts(), latest: monitor.errors().filter((e) => !e.resolved).slice(0, 5) },
      orders: ordersSummary(),
      live: { staffDashboardsOpen: live.adminClients.size, customersTracking: [...live.trackClients.values()].reduce((a, s) => a + s.size, 0), customersBuildingOrders: live.carts.size, agencyStreams: live.agencyClients.size },
      alerts: alerts(), generatedAt: nowISO(),
    };
  }

  /* ── key auth ─────────────────────────────────────────────────────────── */
  const touch = new Map();
  function agencyAuth(level) {
    return (req, res, next) => {
      const raw = (req.get('authorization') || '').replace(/^Bearer\s+/i, '') || req.get('x-api-key') || '';
      if (!raw.startsWith(PREFIX)) return res.status(401).json({ error: 'Missing or invalid API key.' });
      const h = Buffer.from(sha(raw));
      const k = keys().find((x) => !x.revokedAt && x.hash.length === h.length && crypto.timingSafeEqual(Buffer.from(x.hash), h));
      if (!k) { log({ keyId: null, ip: req.ip, method: req.method, path: req.path, result: 'denied' }); return res.status(401).json({ error: 'Missing or invalid API key.' }); }
      if (level === 'control' && k.access !== 'full') return res.status(403).json({ error: 'This key is read-only.' });
      if (ctx.limited('agency:' + k.id, 600, 60000)) return res.status(429).json({ error: 'Rate limit: 600 requests per minute.' });
      req.agencyKey = k;
      // remember last use (written at most once a minute per key)
      if (Date.now() - (touch.get(k.id) || 0) > 60000) {
        touch.set(k.id, Date.now());
        store.setKV('agency:keys', keys().map((x) => (x.id === k.id ? { ...x, lastUsedAt: nowISO(), lastUsedIp: req.ip } : x))).catch(() => {});
      }
      if (req.method !== 'GET') res.on('finish', () => log({ keyId: k.id, keyName: k.name, ip: req.ip, method: req.method, path: req.path, body: req.body, result: res.statusCode }));
      next();
    };
  }
  const by = (req) => `Agency · ${req.agencyKey.name}`;

  /* ── public API (v1) ──────────────────────────────────────────────────── */
  const v1 = '/api/agency/v1';
  app.use(v1, (req, res, next) => {
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Headers', 'Authorization, X-Api-Key, Content-Type');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
    res.setHeader('Cache-Control', 'no-store');
    if (req.method === 'OPTIONS') return res.status(204).end();
    next();
  });
  app.get(v1, agencyAuth('read'), (req, res) => res.json({ name: `${business.name} — agency API`, version: 'v1', access: req.agencyKey.access, endpoints: ENDPOINTS }));
  app.get(`${v1}/ping`, agencyAuth('read'), (req, res) => res.json({ ok: true, online: site().online, at: nowISO() }));
  app.get(`${v1}/status`, agencyAuth('read'), (req, res) => res.json(status()));
  app.get(`${v1}/health`, agencyAuth('read'), (req, res) => res.json(monitor.health()));
  app.get(`${v1}/alerts`, agencyAuth('read'), (req, res) => res.json(alerts()));
  app.get(`${v1}/metrics`, agencyAuth('read'), (req, res) => res.json({ traffic: monitor.traffic(), ...monitor.metrics() }));
  app.get(`${v1}/errors`, agencyAuth('read'), (req, res) => {
    let list = monitor.errors();
    if (req.query.source) list = list.filter((e) => e.source === req.query.source);
    if (req.query.since) list = list.filter((e) => (e.lastAt || e.at) > String(req.query.since));
    if (req.query.unresolved === 'true') list = list.filter((e) => !e.resolved);
    res.json(list.slice(0, Math.min(300, Number(req.query.limit) || 100)));
  });
  app.post(`${v1}/errors/resolve`, agencyAuth('control'), (req, res) => res.json({ resolved: monitor.resolve(req.body?.ids === 'all' ? 'all' : [].concat(req.body?.ids || [])) }));
  app.get(`${v1}/orders`, agencyAuth('read'), (req, res) => {
    const day = (d) => new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Chicago' }).format(new Date(d));
    let list = store.orders();
    if (req.query.from) list = list.filter((o) => day(o.createdAt) >= String(req.query.from));
    if (req.query.to) list = list.filter((o) => day(o.createdAt) <= String(req.query.to));
    if (req.query.status) list = list.filter((o) => String(req.query.status).split(',').includes(o.status));
    res.json(list.slice(0, Math.min(5000, Number(req.query.limit) || 500)).map(adminView));
  });
  app.get(`${v1}/orders/:number`, agencyAuth('read'), (req, res) => { const o = store.findByNumber(Number(req.params.number)); o ? res.json(adminView(o)) : res.status(404).json({ error: 'Order not found.' }); });
  app.post(`${v1}/orders/:number/status`, agencyAuth('control'), async (req, res) => {
    const o = store.findByNumber(Number(req.params.number)); if (!o) return res.status(404).json({ error: 'Order not found.' });
    const r = await changeStatus(o, String(req.body?.status), by(req));
    r.error ? res.status(r.code).json({ error: r.error }) : res.json(adminView(o));
  });
  app.get(`${v1}/menu`, agencyAuth('read'), (req, res) => { const so = new Set(store.settings().soldOut || []); res.json(Object.values(itemsById).map((i) => ({ id: i.id, name: i.name, category: i.category, soldOut: so.has(i.id) }))); });
  app.post(`${v1}/menu/:itemId`, agencyAuth('control'), async (req, res) => {
    const id = req.params.itemId; if (!itemsById[id]) return res.status(404).json({ error: 'Unknown menu item.' });
    const set = new Set(store.settings().soldOut || []); req.body?.soldOut ? set.add(id) : set.delete(id);
    const s = await store.setSettings({ soldOut: [...set] }); toAdmins('settings', { ...s, taxRate: TAX_RATE }); res.json({ id, soldOut: set.has(id) });
  });
  app.get(`${v1}/settings`, agencyAuth('read'), (req, res) => { const { nextNumber, sessionEpoch, ...s } = store.settings(); res.json({ ...s, taxRate: TAX_RATE }); });
  app.post(`${v1}/site`, agencyAuth('control'), async (req, res) => {
    const patch = {};
    if (typeof req.body?.online === 'boolean') patch.siteOnline = req.body.online;
    if (typeof req.body?.message === 'string') patch.offlineMessage = req.body.message.slice(0, 240);
    res.json(await setSite(patch, by(req)));
  });
  app.post(`${v1}/ordering`, agencyAuth('control'), async (req, res) => {
    const patch = {};
    if (typeof req.body?.paused === 'boolean') patch.ordersPaused = req.body.paused;
    if (typeof req.body?.message === 'string') patch.pauseMessage = req.body.message.slice(0, 160);
    if (Number.isFinite(Number(req.body?.prepMinutes))) patch.prepMinutes = Math.max(5, Math.min(90, Math.trunc(Number(req.body.prepMinutes))));
    const s = await store.setSettings(patch); toAdmins('settings', { ...s, taxRate: TAX_RATE }); emit('settings', { by: by(req), patch });
    res.json({ paused: !!s.ordersPaused, message: s.pauseMessage || '', prepMinutes: s.prepMinutes });
  });
  app.post(`${v1}/announcement`, agencyAuth('control'), async (req, res) => {
    const a = { text: String(req.body?.text ?? '').slice(0, 200), active: req.body?.active !== false && !!String(req.body?.text ?? '').trim(), tone: ['info', 'alert', 'promo'].includes(req.body?.tone) ? req.body.tone : 'info' };
    await store.setSettings({ announcement: a }); res.json(a);
  });
  app.post(`${v1}/sessions/revoke`, agencyAuth('control'), async (req, res) => {
    await store.setSettings({ sessionEpoch: (store.settings().sessionEpoch || 0) + 1 });
    toAdmins('signout', { by: by(req) }); res.json({ ok: true, message: 'Everyone signed in to the dashboard has been signed out.' });
  });
  app.get(`${v1}/audit`, agencyAuth('read'), (req, res) => res.json(auditNow().slice(0, Math.min(600, Number(req.query.limit) || 100))));
  app.get(`${v1}/events`, agencyAuth('read'), (req, res) => {
    res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache, no-transform', Connection: 'keep-alive', 'X-Accel-Buffering': 'no', 'Access-Control-Allow-Origin': '*' });
    res.write('retry: 5000\n\n');
    res.write(`event: status\ndata: ${JSON.stringify(status())}\n\n`);
    live.agencyClients.add(res);
    const beat = setInterval(() => res.write(`event: heartbeat\ndata: ${JSON.stringify({ at: nowISO(), online: site().online, alerts: alerts().length })}\n\n`), 20000);
    res.on('close', () => { clearInterval(beat); live.agencyClients.delete(res); });
  });

  /* ── owner-only management (dashboard's hidden Connections window) ──── */
  const owner = staffOnly('owner');
  const publicKey = ({ hash, ...k }) => k;
  app.get('/api/admin/agency', owner, (req, res) => res.json({
    baseUrl: `${req.protocol}://${req.get('host')}${v1}`, keys: keys().map(publicKey), site: site(), webhook: { ...hook(), secret: hook().secret ? '••••' + hook().secret.slice(-4) : '' },
    status: status(), errors: monitor.errors().slice(0, 60), audit: auditNow().slice(0, 60), endpoints: ENDPOINTS,
  }));
  app.post('/api/admin/agency/keys', owner, async (req, res) => {
    const name = String(req.body?.name || 'BDT').trim().slice(0, 40) || 'BDT';
    const access = req.body?.access === 'read' ? 'read' : 'full';
    const secret = PREFIX + crypto.randomBytes(24).toString('base64url');
    const k = { id: crypto.randomUUID(), name, access, prefix: secret.slice(0, PREFIX.length + 6), hash: sha(secret), createdAt: nowISO(), createdBy: req.staff.name, lastUsedAt: null, revokedAt: null };
    await store.setKV('agency:keys', [k, ...keys()]);
    log({ keyId: k.id, keyName: name, ip: req.ip, method: 'KEY', path: 'created', body: { access }, result: `by ${req.staff.name}` });
    res.status(201).json({ key: secret, ...publicKey(k) });
  });
  app.post('/api/admin/agency/keys/:id/revoke', owner, async (req, res) => {
    const list = keys().map((x) => (x.id === req.params.id ? { ...x, revokedAt: nowISO(), revokedBy: req.staff.name } : x));
    await store.setKV('agency:keys', list);
    log({ keyId: req.params.id, ip: req.ip, method: 'KEY', path: 'revoked', result: `by ${req.staff.name}` });
    res.json(list.map(publicKey));
  });
  app.post('/api/admin/agency/site', owner, async (req, res) => {
    const patch = {};
    if (typeof req.body?.online === 'boolean') patch.siteOnline = req.body.online;
    if (typeof req.body?.message === 'string') patch.offlineMessage = req.body.message.slice(0, 240);
    res.json(await setSite(patch, req.staff.name));
  });
  app.post('/api/admin/agency/webhook', owner, async (req, res) => {
    const cur = hook(), b = req.body ?? {};
    let url = cur.url;
    if (typeof b.url === 'string') {
      url = b.url.trim();
      if (url && !/^https:\/\/[^\s]+$/i.test(url)) return res.status(400).json({ error: 'Webhook URL must start with https://' });
    }
    const next = { ...cur, url, active: typeof b.active === 'boolean' ? b.active : cur.active, events: Array.isArray(b.events) ? b.events.filter((e) => ['error', 'site', 'db', 'order.new', 'settings'].includes(e)) : cur.events };
    let secret;
    if (b.rotateSecret || !next.secret) { secret = 'whsec_' + crypto.randomBytes(24).toString('base64url'); next.secret = secret; }
    await store.setKV('agency:webhook', next);
    res.json({ ...next, secret: secret || '••••' + next.secret.slice(-4), secretShownOnce: !!secret });
  });
  app.post('/api/admin/agency/webhook/test', owner, async (req, res) => {
    const h = hook(); if (!h.url) return res.status(400).json({ error: 'Add a webhook URL first.' });
    try { const code = await send(h, 'test', { message: 'Test from the Joy-Full dashboard', by: req.staff.name }); res.json({ ok: code < 300, code }); }
    catch (e) { res.status(502).json({ error: `Could not reach the webhook: ${e.message}` }); }
  });
  app.post('/api/admin/agency/errors/resolve', owner, (req, res) => res.json({ resolved: monitor.resolve(req.body?.ids === 'all' ? 'all' : [].concat(req.body?.ids || [])) }));

  return { siteGate, emit, site };
}

const ENDPOINTS = [
  ['GET', '/ping', 'read', 'Is the site up? Cheap uptime check.'],
  ['GET', '/status', 'read', 'Everything at once: site switch, ordering, health, traffic, errors, today’s orders, live activity and alerts.'],
  ['GET', '/health', 'read', 'Server health: uptime, version, memory, load, database latency.'],
  ['GET', '/alerts', 'read', 'Problems right now that affect the website (critical / warning / info).'],
  ['GET', '/errors?source=server|browser&unresolved=true&since=ISO&limit=100', 'read', 'Server errors, crashes and visitors’ browser errors (repeats grouped with a count).'],
  ['POST', '/errors/resolve  {"ids":["…"]} or {"ids":"all"}', 'control', 'Mark errors as resolved.'],
  ['GET', '/metrics', 'read', 'Traffic, error rate, latency per route, slow requests, 404s, real page-load times.'],
  ['GET', '/orders?from=YYYY-MM-DD&to=YYYY-MM-DD&status=received,preparing&limit=500', 'read', 'Order history with every detail and timeline.'],
  ['GET', '/orders/:number', 'read', 'One order.'],
  ['POST', '/orders/:number/status  {"status":"preparing|ready|completed|cancelled|received"}', 'control', 'Move an order (customer sees it live on JOYTRACK).'],
  ['GET', '/menu', 'read', 'Menu items and which are sold out.'],
  ['POST', '/menu/:itemId  {"soldOut":true}', 'control', 'Mark an item sold out / available.'],
  ['GET', '/settings', 'read', 'Current site settings.'],
  ['POST', '/site  {"online":false,"message":"Back at 2pm"}', 'control', 'Turn the whole public website OFF / ON (dashboard and API keep working).'],
  ['POST', '/ordering  {"paused":true,"message":"…","prepMinutes":15}', 'control', 'Pause / resume online ordering, change prep time.'],
  ['POST', '/announcement  {"text":"…","tone":"info|alert|promo","active":true}', 'control', 'Banner across the top of the website.'],
  ['POST', '/sessions/revoke', 'control', 'Sign everyone out of the staff dashboard.'],
  ['GET', '/audit?limit=100', 'read', 'Log of every control action taken through the API.'],
  ['GET', '/events', 'read', 'Live stream (Server-Sent Events): status, error, order.new, site.*, db, heartbeat.'],
].map(([method, path, access, description]) => ({ method, path, access, description }));

function offlinePage(message, business) {
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(business.name)} · Back soon</title>
<link rel="icon" href="/photos/joyfull-logo.webp"><link href="https://fonts.googleapis.com/css2?family=Archivo:wght@800;900&family=Geist:wght@400;600&display=swap" rel="stylesheet">
<style>*{box-sizing:border-box}body{margin:0;min-height:100dvh;display:grid;place-items:center;padding:24px;font-family:Geist,system-ui,sans-serif;color:#fff;text-align:center;background:radial-gradient(120% 90% at 50% 30%,#f2453f,#c92a2a 55%,#7d0d13)}
main{max-width:560px}img{width:96px;height:96px;border-radius:50%;background:#fff;box-shadow:0 20px 40px -18px rgba(0,0,0,.5)}h1{font:900 clamp(38px,8vw,64px)/.95 Archivo,system-ui,sans-serif;letter-spacing:-.02em;margin:22px 0 12px;text-transform:uppercase}
p{font-size:18px;line-height:1.5;margin:0 0 10px;opacity:.95}a{display:inline-block;margin-top:18px;padding:14px 22px;border-radius:999px;background:#fff;color:#c92a2a;font-weight:700;text-decoration:none}small{display:block;margin-top:26px;opacity:.75}</style></head>
<body><main><img src="/photos/joyfull-logo.webp" alt="${esc(business.name)}"><h1>We’ll be right back</h1><p>${esc(message || 'Our website is taking a short break. The cafe is still serving — come see us!')}</p>
<a href="${esc(business.phoneHref)}">Call ${esc(business.phone)}</a><small>${esc(business.street)} · ${esc(business.city)}</small></main></body></html>`;
}
